@mixin button-base($padding: 1rem, $radius: 0.5rem) {
  padding: $padding;
  border-radius: $radius;
  border: none;
  cursor: pointer;
  font-family: inherit;
}

.c-btn-primary {
  @include button-base;
  background: $primary;
  color: white;
}

.c-btn-secondary {
  @include button-base(0.75rem, 0.25rem);
  background: transparent;
  color: $primary;
  border: 1px solid $primary;
}

